style.css:
@-moz-document domain("sohu.com") {
/* ============================================================
     Palette
     base bg          #14181d
     elevated surface #1c2128
     header/footer    #0d1117
     border subtle    #262c33
     border component #2d333b
     text primary     #e6edf3
     text reading     #c8d0d9
     text muted       #8b949e
     link/accent      #5fb0e6 (hover #9bd4ff)
     brand orange     #ff7a45 (Sohu red-orange, tuned for dark)
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Common page wrappers that carry a hardcoded white background */
  .article-page,
  .index,
  .main-content,
  .content,
  #main,
  .wrapper,
  .page,
  .container,
  .top-box-wrapper,
  .wrapper-box,
  .main-box,
  .box-wrapper {
    background-color: transparent !important;
  }

  /* classic-homepage / Sohu-video promo strip (light gradient art) */
  .swf-top,
  .swf-top a,
  .swf-banner {
    background-color: #1c2128 !important;
    background-image: none !important;
  }

  /* home center "点击进入·经典版首页" classic-homepage entry banner (#entrance):
     a single raster PNG with a cream background baked in (fox mascot + text +
     yellow "经典版首页" pill). Luminance-invert to dark; the hue-rotate preserves
     the fox red-orange + yellow-pill identity while flipping the cream to dark. */
  #entrance {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* home top-right compliance-badge carousel (#report .jubao-con): official
     report / supervision badges rendered as raster image links. Three frames
     ship a light background (网络监督专区 white, 网上有害信息举报专区 light-blue,
     社会主义核心价值观 cream) that glare on the dark page; the 学习强国 / 伟大的变革
     frames are already dark red and must stay untouched. Luminance-invert only
     the light frames — the hue-rotate keeps the red/blue emblem hues. */
  #report .jubao-con.jubao01,
  #report .jubao-con.jubao04,
  #report .jubao-con.jubao05 {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* light-grey filler tiles / plugin modules on the home grid */
  .content-other-item,
  .other-item,
  .grey-box,
  .gray-box,
  .title-cut,
  .picture-group,
  .author-subscribe-area,
  .fun-frag,
  .extend-mod,
  .other-modA,
  .other-modB,
  .plugin,
  .yule-play,
  .sports-match,
  .stock-tabs-c,
  .stock-box,
  .fun-list,
  .mod-box {
    background-color: #1c2128 !important;
  }

  /* Soften every light border into a subtle dark one */
  * {
    border-color: #262c33 !important;
  }

  /* ---------- Header / top nav ---------- */
  .sohu-head,
  header,
  .header,
  .area-header,
  .tbl-explore-more-site-header {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  .sohu-head a,
  header a,
  .header a,
  .sohu-head-box,
  .top-head,
  .head-item,
  .head-item a,
  .login,
  .login-area,
  .login-area a {
    color: #e6edf3 !important;
    background-color: transparent !important;
  }

  .sohu-head a:hover,
  header a:hover,
  .head-item a:hover {
    color: #9bd4ff !important;
  }

  .divide-line {
    background-color: #2d333b !important;
  }

  /* primary nav bar (channels) */
  .nav,
  .nav.area,
  .menu,
  .nav-list,
  .channel,
  .channel-list {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .nav a,
  .menu a,
  .channel a {
    color: #c4cdd6 !important;
  }

  .nav a:hover,
  .menu a:hover,
  .channel a:hover {
    color: #ff7a45 !important;
  }

  /* ---------- Search box ---------- */
  .search-input,
  input[type="text"],
  input[type="search"],
  input.text,
  .search input,
  textarea {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .search-input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  .search-btn,
  .search button,
  button.search {
    background-color: #ff7a45 !important;
    color: #14181d !important;
    border-color: #ff7a45 !important;
  }

  /* ---------- Home aggregator grid ---------- */
  .main-left,
  .main-right,
  .left,
  .right,
  .scroll,
  .index-focus,
  .focus,
  .swiper-focus,
  .block,
  .news-box,
  .feed,
  .feed-list,
  .feed-content,
  .list,
  .card {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* section / block labels + hardcoded-dark headlines/metadata */
  .title,
  .block-title,
  .focus-title,
  .news-title,
  .titleW,
  .tab,
  .col-title,
  .other-title,
  .tt,
  .txt,
  .focus-t,
  .swf-tt,
  h2,
  h3 {
    color: #e6edf3 !important;
  }

  /* read counts / muted metadata that ship hardcoded grey */
  .read-num,
  .read-count,
  .num,
  .source-name,
  em.read-num {
    color: #8b949e !important;
  }

  /* headline links */
  a,
  .title a,
  .news-title a,
  .feed a,
  .list a {
    color: #c4cdd6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* hot-list / ranking widgets */
  .rank,
  .ranklist,
  .hot,
  .news-rank,
  [class*="rank"],
  [class*="hot-list"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* thumbnails keep their own colors; just no white tile behind them */
  .pic,
  .img-do,
  .ad-focus,
  .thumb,
  .pic-box {
    background-color: transparent !important;
  }

  /* home right-column widget (e.g. "北京要闻"): each headline row is an
     a.shadow with a hardcoded rgb(249,249,249) pill bg — flatten it.
     The .qrcode stays white (it's a scannable QR code, like a logo). */
  a.shadow {
    background-color: transparent !important;
  }

  /* home sidebar plugin tab bars (e.g. .sports-match 赛事直播 / 精彩回放):
     the selected tab ships a light-grey rgb(238,238,238) box + near-black
     text (light-on-light) and the idle tab ships near-black text
     (dark-on-dark). Give the pair a readable dark-theme treatment. */
  .head-tab .left-tab,
  .head-tab .right-tab,
  .plugin .left-tab,
  .plugin .right-tab,
  .sports-match .left-tab,
  .sports-match .right-tab {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .head-tab .activeTab,
  .plugin .activeTab,
  .sports-match .activeTab {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  /* home sports-match schedule rows (a.match): team names ship near-black
     rgb(17,17,17) and the date / round metadata ships dim rgb(102,102,102)
     — both dark-on-dark on the elevated widget. Lift names to primary and
     metadata to muted; the VS badge + team logos keep their own colors. */
  .sports-match .match .left-text,
  .sports-match .match .right-text,
  .match .match-content .left-text,
  .match .match-content .right-text {
    color: #e6edf3 !important;
  }

  .sports-match .match .match-head span,
  .sports-match .match .normal-text,
  .match .match-head span,
  .match .match-head .normal-text {
    color: #8b949e !important;
  }

  /* home real-estate promo widget (.focus-ad, 楼市精选 / 帮你买房): the
     container ships a light rgb(249,249,249) panel and the selected
     .ftab-nav-item ships an rgb(238,238,238) pill with near-black text. */
  .focus-ad {
    background-color: transparent !important;
  }

  .focus-ad .ftab-nav-item.active,
  .focus-ad .ftab-nav-item.active span {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  .focus-ad .ftab-nav-item span {
    color: #c4cdd6 !important;
  }

  /* home 快速找车 auto widget (.car-right-box): the 选品牌 / 选车型 select
     boxes ship white rgb(255,255,255) fields, and the car-category labels
     (SUV / MPV / 跑车 …) ship dim rgb(102,102,102) dark-on-dark */
  .car-right-box .selbox,
  .car-right-box .seltit {
    background-color: #1c2128 !important;
  }

  .car-right-box .auto-hot-model li a span,
  .car-right-box .car-tuijian span {
    color: #c4cdd6 !important;
  }

  /* home 搜狐号 subscribe card (.author-subscribe .container-box): each
     media-account source name ships near-black rgb(17,17,17) dark-on-dark */
  .author-subscribe .container-box .name,
  .container-box a.content-left .name {
    color: #c4cdd6 !important;
  }

  /* home stock widget selected tab uses li.active-bg with a white box */
  .stock-tabs-c .stock-header li.active-bg,
  li.active-bg {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  /* footer license block (.service-info .license): one cert label
     (#internetPass) ships a dim rgb(64,64,64) — lift the whole block */
  .license,
  .license a,
  .license span,
  #internetPass {
    color: #c4cdd6 !important;
  }

  /* ---------- Article reader (the key surface) ---------- */
  #article-container,
  .article-page .main,
  .left.main,
  .text,
  .article-info {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* the long-form body — soft off-white, comfortable for reading */
  article,
  #mp-editor,
  .article,
  #mp-editor p,
  .article p,
  .text p,
  #mp-editor span,
  .article span,
  #mp-editor div,
  .article div,
  #mp-editor font,
  .article font,
  #mp-editor li,
  .article li {
    color: #c8d0d9 !important;
    background-color: transparent !important;
  }

  /* title */
  .article-page h1,
  #article-container h1,
  .article-title,
  h1 {
    color: #e6edf3 !important;
  }

  /* byline / date / source / author */
  .article-info,
  .article-info a,
  .time,
  .source,
  .author,
  .media-name,
  .user-info,
  .statement,
  .declare {
    color: #8b949e !important;
  }

  .article-info a:hover,
  .media-name a:hover {
    color: #9bd4ff !important;
  }

  /* blockquotes */
  #mp-editor blockquote,
  .article blockquote,
  blockquote {
    background-color: #1c2128 !important;
    border-left-color: #2d333b !important;
    color: #c8d0d9 !important;
  }

  /* in-body links + the "返回搜狐，查看更多" link */
  #mp-editor a,
  .article a,
  .text a,
  .backword,
  .show-all {
    color: #5fb0e6 !important;
  }

  #mp-editor a:hover,
  .article a:hover,
  .backword:hover {
    color: #9bd4ff !important;
  }

  /* code inside articles */
  #mp-editor pre,
  .article pre,
  #mp-editor code,
  .article code {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---------- Author card / sidebar widgets on the article page ---------- */
  .author-card-c,
  .author-card,
  .author-info,
  .author-subscribe,
  .godR,
  .hot-article,
  .hot-article.bord,
  .side-box,
  .sidebar-box {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* right-hand article sidebar wrapper */
  .right-side-abroad,
  .right-side,
  #right-side-bar,
  .area-side {
    background-color: transparent !important;
  }

  /* ---------- Article page redesign (mpfe template) ---------- */
  /* author profile card (#user-info) ships a hardcoded white panel;
     its stat labels (文章 / 总阅读) ship a dim rgb(102,102,102) */
  #user-info {
    background-color: #1c2128 !important;
  }

  #user-info .user-num li {
    color: #8b949e !important;
  }

  /* author card "查看TA的文章>" button ships a light rgb(249,249,249) pill */
  #user-info .user-more {
    background-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  /* right-rail "热门精选" image-card widget + its top gallery ship white */
  #topScrollPic,
  .hot-atlas,
  .hot-atlas .con,
  .hot-atlas ul {
    background-color: transparent !important;
  }

  /* left action column (#shareInteraction): each like/comment/favorite/share
     control is a rgb(248,248,248) rounded button holding a dark raster glyph,
     and the count/label under it ships near-black (dark-on-dark). Darken the
     button, flip the glyph light, and lift the labels. */
  #shareInteraction .icon,
  #shareInteraction .item,
  .share-interaction-c .icon,
  .share-interaction-c .item {
    background-color: #1c2128 !important;
  }

  #shareInteraction .icon .no-like-icon,
  #shareInteraction .icon .like-icon,
  #shareInteraction .icon .no-collection-icon,
  #shareInteraction .icon .collection-icon,
  #shareInteraction .icon .comment-icon,
  #shareInteraction .icon .share-icon,
  #shareInteraction .item > img {
    filter: invert(1) brightness(1.7) !important;
  }

  #shareInteraction .count,
  .share-interaction-c .count {
    color: #8b949e !important;
  }

  /* "扫码打开手机搜狐网" QR-scan caption ships near-black text */
  .phone-scan-c .text1,
  .phone-scan-c .text1 span,
  .phone-scan-c .border-font {
    color: #c4cdd6 !important;
  }

  /* "内容举报" report link ships a dim rgb(96,96,96) */
  #articleReport .report,
  #articleReport .report-c span {
    color: #8b949e !important;
  }

  /* "大家都在看" recommendation heading ships a near-black inner span */
  #articleAllsee .title,
  #articleAllsee .title span,
  .article-allsee .title,
  .article-allsee .title span {
    color: #e6edf3 !important;
  }

  /* lazy-image placeholders paint a white ::before behind the <img>
     (flashes white on slow/broken load in these article widgets, and on
     the main reading surface itself: article-body <img> in #mp-editor /
     .article paint a full-size white ::before box) */
  .img-do img::before,
  .img-do img::after,
  .allsee-image img::before,
  .allsee-image img::after,
  .allsee-item img::before,
  .allsee-item img::after,
  .hot-atlas img::before,
  .hot-atlas img::after,
  article#mp-editor img::before,
  article#mp-editor img::after,
  #mp-editor img::before,
  #mp-editor img::after,
  .article img::before,
  .article img::after {
    background-color: #1c2128 !important;
    color: #8b949e !important;
  }

  /* author / editor name keeps the Sohu red identity, lifted for dark */
  .editor-name,
  .username,
  .unlogin-text,
  .author-name {
    color: #ff6a5a !important;
  }

  /* ---------- Related stories / recommendations ---------- */
  .recommend,
  .relevant,
  .related,
  .recommend-list,
  .area-business,
  .box,
  .statement,
  .recommend-art,
  .sub-art {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* related-list headings, source names and subtitles ship hardcoded dark */
  .recommend .name,
  .relevant .name,
  .related .name,
  .recommend-art .name,
  .hot-article .name,
  .groom-read .name,
  .godR .name,
  .author-card-c .name,
  .right-side-abroad .name,
  .recommend h2,
  .recommend h3,
  .recommend-title {
    color: #e6edf3 !important;
  }

  .sub-art,
  .recommend .sub-art,
  .groom-read .sub-art,
  .recommend .desc,
  .recommend-art .desc {
    color: #c4cdd6 !important;
  }

  .recommend a,
  .relevant a,
  .related a,
  .hot-article a {
    color: #c4cdd6 !important;
  }

  .recommend a:hover,
  .relevant a:hover {
    color: #9bd4ff !important;
  }

  /* ---------- Comments ---------- */
  #comment_area,
  .comment-area,
  .comment,
  .comment-list,
  .comment-item,
  .cmt-item,
  .reply,
  .comment-tabs,
  .comment-head {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* comment tab labels (最新评论 / 热门评论) ship hardcoded near-black */
  .tab-item,
  .comment-tab,
  .comment-tab span,
  .comment-tabs .tab,
  .comment-head .tab,
  .comment-title {
    color: #c4cdd6 !important;
  }

  .tab-item.active,
  .comment-tab .active,
  .comment-tabs .tab.active {
    color: #e6edf3 !important;
  }

  .comment-item .name,
  .comment .name,
  .cmt-name {
    color: #e6edf3 !important;
  }

  .comment-item .content,
  .comment .content,
  .cmt-content {
    color: #c8d0d9 !important;
  }

  .comment-item .time,
  .comment .time {
    color: #8b949e !important;
  }

  /* comment @-mentions (@搜狐小编) + inline hot-topic links ship a hardcoded
     dark blue (rgb(20,60,168) / rgb(35,87,207)) — dark-on-dark on the feed.
     Lift both to the readable accent blue. */
  .comment-content-text .comment-at,
  .comment .comment-at,
  .comment-link .link-title,
  .comment-content .comment-link {
    color: #5fb0e6 !important;
  }

  /* comment-box submit toolbar (avatar / emoji / @ row) ships rgb(248,248,248) */
  .comment-submit .footer-btns,
  .footer-btns,
  .comment-edit-area,
  .comment-input-area {
    background-color: #1c2128 !important;
  }

  /* "推荐阅读" recommended-reading heading (#groomRead) ships hardcoded near-black */
  .groom-read,
  .groom-read .title,
  .groom-read .title span,
  .recommend-read,
  .read-title {
    color: #c4cdd6 !important;
  }

  .groom-read .title,
  .groom-read .title span {
    color: #e6edf3 !important;
  }

  /* like counter ("首赞" / read counts) + author-column metadata */
  .article-like,
  .article-like .like-text,
  .like-text,
  .like-num,
  .praise-num,
  em.read-num,
  .read-num em {
    color: #8b949e !important;
  }

  /* ---------- Sidebars ---------- */
  .area-side,
  .side,
  .sidebar,
  aside {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* ============================================================
     Channel / category pages (news.sohu.com, business.sohu.com, …)
     A separate modern template: the whole page lives under #Index,
     content blocks are id="block2..36" / id="TPL*_pc_*" / id="FS*" /
     id="Block_*" / id="ChannelNavigation*" with hashed timestamps, and
     the layout grid is built from classless wrapper <div>s. White is
     carried by those wrappers + per-element hardcoded near-black text.
     Neutralize the whole #Index subtree to the dark base, then
     re-establish opaque surfaces on floating menus / inputs / footer.
     ============================================================ */
  #Index,
  #Index > div,
  #Index div[id^="block"],
  #Index div[id^="Block_"],
  #Index div[id^="TPL"],
  #Index div[id^="FS"],
  #Index div[id^="Navigator"],
  #Index div[id^="ChannelNavigation"],
  #Index div:not([class]),
  #Index .single-image-text,
  #Index .imageBox,
  #Index .textBox,
  #Index .image-img-content,
  #Index .item_img,
  #Index .cover-image,
  #Index .left,
  #Index a.swf-top,
  #Index [class*="Contsize"],
  #Index .navigatorContainer,
  #Index .cbd-recommend,
  #Index .mention,
  #Index .padding-bottom,
  #Index .zx {
    background-color: transparent !important;
  }

  /* business.sohu.com stock widgets carry their own white panels */
  #Index .searchForm,
  #Index .stock-info,
  #Index .stock-c,
  #Index .stock-c .content {
    background-color: #1c2128 !important;
  }

  /* the market-index mini-chart (上证指数 …) is a third-party raster PNG
     (d1.biz.itc.cn/…/index_*.png) with a hardcoded white background that
     glares on the dark stock widget. Luminance-invert it to dark; the
     hue-rotate preserves the semantic up/down line + red reference dashes. */
  .stock-image img,
  .stock-c img,
  .stock-info img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* stock widget A股 / 美股 selected tab ships a white rgb(255,255,255) box */
  .tab-item.item-active,
  li.item-active {
    background-color: #1c2128 !important;
    color: #ff7a45 !important;
  }

  /* site-wide floating utility toolbar (refresh / phone-scan / feedback pencil /
     back-to-top): each is a white button holding a dark raster glyph. The toolbar
     ships in several DOM shapes across pages — legacy channel (.back-top-link),
     the www home Vue widget (.refresh-btn / .phone-scan / .btn.user-feedback /
     .btn.back-top) and the article Vue widget (#float-btn .float-links li…). Darken
     every white surface and flip its dark glyph light. The yellow Sohu-app button
     (.back-sohu) is a separate brand element, left as its brand color. */
  .user-feedback .user-feedback-link,
  .back-top-link,
  .refresh-btn,
  .phone-scan,
  .btn.user-feedback,
  .btn.back-top,
  #float-btn .float-links li.user-feedback,
  #float-btn .float-links li.back-top,
  #float-btn .float-links li.back-top span {
    background-color: #1c2128 !important;
  }

  .user-feedback .user-feedback-link img.tool_img,
  .back-top-link img.tool_img,
  .refresh-btn .refresh-icon,
  .phone-scan img,
  .btn.user-feedback img.fb-icon,
  .btn.back-top img.fb-icon,
  #float-btn .float-links li.user-feedback img.fb-icon,
  #float-btn .float-links li.back-top img.fb-icon {
    filter: invert(1) brightness(1.7) !important;
  }

  /* "我的自选" hot-stock widget: the centered divider label (以下是热门股票)
     ships a rgb(248,248,248) pill that traps its own light-grey text
     (light-on-light). Mask it with the page base so the label reads. */
  .hot-title-title {
    background-color: #14181d !important;
  }

  /* channel news thumbnail containers (#Index .item .img) keep a white
     box behind the photo — flashes white on slow/broken image load */
  #Index .img,
  #Index .item .img {
    background-color: transparent !important;
  }

  /* opaque dark surfaces: top channel-nav header, stock ticker widgets,
     PWA "add to desktop" promo, side plugin tiles, page footer */
  .nav_header,
  .nav_container,
  .navigation-head,
  .stock-tabs-c,
  .stock-box,
  .stock-zs,
  .add-desktop,
  .add-desktop-c,
  .pwa,
  .side-wrap-plugin-bacground,
  .plugin-side-right,
  #hot-news-focus-region,
  .PCBottomCopyright {
    background-color: #14181d !important;
  }

  /* "添加搜狐网首页至浏览器收藏夹" PWA promo ships hardcoded near-black text */
  .add-desktop,
  .add-desktop .collection-c,
  .add-desktop .right,
  .add-desktop .title-single,
  .add-desktop .title-double,
  .add-desktop .desc {
    color: #c4cdd6 !important;
  }

  /* home "title-cut" channel-header pills use a light-grey li::after divider */
  .title-cut ul li::after,
  .title-cut li::after {
    background-color: #2d333b !important;
  }

  /* breaking-news "新闻链" chain rows (TPLCommandAreaFirstScreen) ship a
     white rgb(248,248,248) :hover highlight — keep a dark elevated one */
  .text-chain-item:hover {
    background-color: #1c2128 !important;
  }

  /* headline-list rows across the channel templates ship a hardcoded white
     rgb(248,248,248) :hover highlight — running the pointer down a list paints
     a "moving white bar" one row at a time, and our lifted light text on it
     reads light-on-light. Darken every per-widget row class to a dark elevated
     surface (business .tpl-text-item-block; news.sohu.com .text-li /
     .multiple-text / .TPLTextItem / hot-list / video / house rows). */
  .tpl-text-item-block:hover,
  .text-li:hover,
  .multiple-text:hover,
  .multiple-text-item .multiple-text:hover,
  .TPLTextItem a:hover,
  .HotArticle .item:hover,
  .commonside_item:hover,
  .tpl-video-image-item a:hover,
  .sub-item-yule .sub-video-item:hover,
  .sub-item-yule .video-item-active:hover,
  .house-article .article-item > a:hover,
  .FeedItemOperate .rightOperaterListItem:hover {
    background-color: #1c2128 !important;
  }

  /* floating channel-nav "more" dropdown stays solid + opaque */
  .navigation-more-list,
  .navigation-more-show,
  .navigation-more-box,
  .navigation-layer,
  .navigation-layer-content {
    background-color: #1c2128 !important;
  }

  /* channel feed-category left menu (.feed-mul-content-left): the selected
     row ships a white rgb(248,248,248) pill trapping light text (light-on-
     light). Give it a dark elevated surface + the Sohu accent. */
  .feed-mul-content-left a.active-menu,
  .list-content a.active-menu,
  #Index a.active-menu {
    background-color: #1c2128 !important;
  }

  #Index a.active-menu,
  #Index a.active-menu .first-title,
  .list-content a.active-menu .first-title {
    color: #ff7a45 !important;
  }

  /* channel search field (rgb(242,242,242)) */
  .search-input-wrapper,
  input.search-input {
    background-color: #1c2128 !important;
  }

  #Index input.search-input {
    color: #e6edf3 !important;
  }

  /* channel text: the template hardcodes near-black per element, so
     lift every text node under #Index (and the nav header / footer)
     to a readable body color */
  #Index,
  #Index *,
  .nav_header,
  .nav_header *,
  .nav_container *,
  .navigation-more-list *,
  .PCBottomCopyright,
  .PCBottomCopyright * {
    color: #c4cdd6 !important;
  }

  /* headlines + section titles brighter */
  #Index .ImageTextCover,
  #Index .shadow,
  #Index .title-text,
  #Index .item-title,
  #Index .tpl-middle-title-left,
  #Index .tpl-middle-title-text,
  #Index h1,
  #Index h2,
  #Index h3,
  #Index .title {
    color: #e6edf3 !important;
  }

  /* active channel nav tab + selected feed tab keep the Sohu accent */
  .nav_item.nav_active,
  #Index .cur.focus-tab,
  #Index .text-info-active {
    color: #ff7a45 !important;
  }

  /* ---------- Cards / elevated panels that keep a real background ---------- */
  .box-shadow,
  .panel,
  .module,
  .widget {
    background-color: #1c2128 !important;
  }

  /* ============================================================
     Google Funding Choices consent dialog (.fc-consent-root) — a
     full-screen white CMP sheet shown before ads load on article
     pages. Its stylesheet loads AFTER ours, so scope every rule from
     .fc-consent-root to out-specify it; dark the sheet + lift its
     dark Material text (blue Consent/Manage buttons stay brand blue).
     ============================================================ */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-choice-dialog,
  .fc-consent-root .fc-header,
  .fc-consent-root .fc-footer {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .fc-consent-root .fc-dialog h1,
  .fc-consent-root .fc-dialog h2,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog li,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog a,
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-dialog-content {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-faq-contents {
    background-color: #14181d !important;
  }

  .fc-consent-root .fc-dialog hr,
  .fc-consent-root .fc-dialog [class*="divider"] {
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }

  /* "Manage options" preferences panel: sticky header + per-purpose
     cards + manage-vendors row all ship a literal white surface. */
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-preference-container,
  .fc-consent-root .fc-navigation-button,
  .fc-consent-root .fc-manage-vendors,
  .fc-consent-root [class*="preferences-container"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .fc-consent-root .fc-preference-container {
    background-color: #21262d !important;
  }

  /* ============================================================
     Taboola sponsored-content widget ("你可能会喜欢" / "热门精选")
     at the bottom of article pages. Stable trc_* SDK classes.
     Titles + source labels ship hardcoded near-black; thumbnail
     fade overlays ship a white gradient.
     ============================================================ */
  .trc_rbox_header_span,
  .trc-widget-container .video-title,
  .videoCube .video-title,
  .trc_spotlight_item .video-title,
  .trc_rbox_div .video-label {
    color: #c8d0d9 !important;
  }

  .trc-source-name,
  .videoCube .branding,
  .trc_desktop_attribution_link span,
  .trc_desktop_disclosure_link span,
  .trc-widget-footer span {
    color: #8b949e !important;
  }

  .trc_exclude_overlay.trc_fade,
  .videoCube .trc_fade,
  .trc_popover.trc_popover_fade {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* ============================================================
     Search results (search.sohu.com) — its own template:
     body.channel-index > .wrap-box, a white header band, white
     result cards (.cards-small-*), a white right rail (搜狐热搜),
     a white autocomplete dropdown and a light-pink topic banner
     (raster background-image). Neutralize to the dark base, then
     re-establish opaque elevated surfaces + readable text.
     ============================================================ */
  .channel-index,
  .wrap-box,
  .search-header-wrap,
  .search-content-wrap,
  .search-content-box,
  .search-content-content,
  .search-content-left,
  .search-content-left-nav,
  #news-list,
  #news-list > div,
  .cards-small-img,
  .cards-small-plain,
  .cards-content,
  .cards-content-left,
  .cards-content-right,
  .topic-img,
  .topic-content {
    background-color: transparent !important;
  }

  /* topic banner ships a light-pink raster background-image */
  .topic-content-box {
    background-image: none !important;
    background-color: #1c2128 !important;
  }

  /* hot-search right rail = elevated card; autocomplete = floating surface */
  .search-content-right,
  #suggest-list-wrap,
  #input-suggest-list-wrap,
  .input-suggest-list-wrap,
  .input-suggest-list-item,
  .input-base-list-item {
    background-color: #1c2128 !important;
  }

  /* search-box autocomplete suggestion rows ship near-black text */
  .input-suggest-list-item,
  .input-suggest-list-item a,
  .input-base-list-item {
    color: #c4cdd6 !important;
  }

  .input-suggest-list-item:hover,
  .input-base-list-item:hover {
    background-color: #262c33 !important;
  }

  /* result + hot-search headings; media-account suggestion titles */
  .cards-content-title,
  .cards-content-title a,
  .cards-content-right-title,
  .cards-content-right-title a,
  .search-content-right-title,
  .section-item-right-title,
  .section-item-right-title a,
  .hotSearchList-item-text,
  .hotSearchList-item-text a {
    color: #e6edf3 !important;
  }

  /* result snippets, sources, search tabs, "查看全部" */
  .cards-content-right-desc,
  .cards-content-right-desc a,
  .cards-content-right-comm,
  .section-item-right-desc,
  .search-content-left-nav .nav-item,
  #nav-left > p,
  #nav-right > p,
  #nav-column > p,
  #find-all,
  #suggest-list-wrap a {
    color: #c4cdd6 !important;
  }

  /* active search tab + keyword highlight keep the Sohu accent */
  .search-content-left-nav .nav-item.active,
  .search-content-left-nav .active {
    color: #ff7a45 !important;
  }

  /* ============================================================
     Author / media profile (mp.sohu.com /profile) — the feed
     filter-tab bar (最新 / 动态 / 育儿 …) ships a white rank bar
     with a white active-tab box.
     ============================================================ */
  .tpl-rank-bar,
  .tap-rank-tap,
  .outtap,
  .leftpart,
  .rightpart {
    background-color: transparent !important;
  }

  .active_tap {
    background-color: #1c2128 !important;
  }

  .active_text {
    color: #ff7a45 !important;
  }

  .default_text,
  .inner_tap,
  .tap-rank-tap .tap-item {
    color: #c4cdd6 !important;
  }

  /* ---------- Footer ---------- */
  .footer,
  #footer,
  .footer.area,
  .copyright,
  .area-footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  .footer a,
  #footer a,
  .copyright a {
    color: #8b949e !important;
  }

  .footer a:hover,
  #footer a:hover {
    color: #c4cdd6 !important;
  }

  /* ---------- Brand accent ---------- */
  /* Sohu uses a red-orange identity; keep the hue, tune for dark */
  .backword,
  .logo-text,
  .more-link {
    color: #ff7a45 !important;
  }

  ::selection {
    background-color: #ff7a45 !important;
    color: #14181d !important;
  }
}
